PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT ?university ?foundingDate
WHERE {
  VALUES ?university {
    <http://dbpedia.org/resource/Universidad_Autónoma_de_La_Laguna>
    <http://dbpedia.org/resource/Penang_Free_School>
  }
  ?university dbo:foundingDate ?foundingDate .
}
ORDER BY ?foundingDate
LIMIT 100

